// ── UI i18n: flat dot-key string tables + locale state ──
// t(key, params)      → translated string, {param} placeholders substituted
// tc(key, n, params)  → plural-aware: resolves `${key}.one|few|many` by locale rules
// setLocale(lang)     → switch active locale (unknown → 'en'); callers re-render
//
// Values are render-time lookups — modules must call t() inside render functions,
// never capture translated strings in module-level constants (they would freeze
// at import time, before the project locale is known).

