  // Voice input (tt-audio-input)
  // (C1262) record/stop double as BOTH title and aria-label on every icon-only mic button
  // (setMicButtonLabel(), audio-recorder.js) — keep {shortcut} in every locale, i18n.test.js
  // asserts it.
  'voice.record': 'Record voice ({shortcut})',
  'voice.stop': 'Stop recording ({shortcut})',
  'voice.micDenied': 'Microphone access denied',
  'voice.transcribeFailed': 'Transcription failed: {msg}',
  // (TPT9165) The recording widget shows no words: recordingToast is its screen-reader label, and
  // stopRecording the title + aria-label of its Stop button, which ends every live recording and
  // hands each to transcription. Keep {shortcut} in both, in every locale — i18n.test.js asserts it.
  'voice.recordingToast': 'Recording… {shortcut} to stop',
  'voice.stopRecording': 'Stop recording and transcribe ({shortcut})',
  'voice.stoppingIn': 'Stopping in {n}s…',
  // (C1206) The global shortcut matched but resolveVoiceTarget() found nothing to record into —
  // shown instead of the combo silently doing nothing (see chat-ui.js's registerVoiceShortcut()).
  'voice.noTarget': 'No voice input available here',
  // (C1206) Recording toast hint shown while the silence watchdog is still unarmed — no speech
  // has been heard yet this recording, so the 10s auto-stop timer hasn't started (see
  // voice-silence.js). Distinct from voice.stoppingIn so a dead mic looks visibly different from
  // a normal pre-speech pause.
  'voice.noSoundYet': 'No sound reaching the microphone yet…',
  // (C1211) Mic locked because objective chat turn is streaming — disabled tooltip AND
  // the toast shown when the global shortcut is pressed against a locked mic.
  'voice.busyAwaitingReply': "Waiting for the agent's reply…",
  // (C1186) POST /api/transcribe error codes -> localized messages. See
  // ERROR_CODE_I18N_KEY in voice-errors.js for the code->key mapping; voice.transcribeFailed
  // above stays the fallback for any code not in that map (including no code at all).
  'voice.errKeyInvalid': 'AssemblyAI rejected the configured key — check your key in Settings > Voice',
  'voice.errEngineUnavailable': 'Local transcription is unavailable — {reason}',
  'voice.errTooLarge': 'Recording is too large to transcribe (25 MB limit)',
  'voice.errTimeout': 'Transcription timed out — try a shorter recording',
  // (C1203) Was one static string for every AssemblyAI failure (UPSTREAM and NETWORK both hit
  // this key, TIMEOUT and POLL_TIMEOUT both hit voice.errTimeout) — the "generic failure" this
  // task fixed. Now interpolates the real AssemblyAI message; errNetwork/errRequestTimeout/
  // errPollTimeout below are new, one per distinct code.
  'voice.errUpstream': 'Transcription service error — {detail}',
  'voice.errNetwork': 'Could not reach AssemblyAI — check your connection',
  'voice.errRequestTimeout': 'AssemblyAI did not respond in time — try again',
  'voice.errPollTimeout': 'Transcription is taking too long — try a shorter recording',
  // (C1197) Sub-reasons for voice.errEngineUnavailable's {reason} — one per
  // LocalAsrUnavailableError.reasonCode (local-asr.js), so the toast finally differs by cause
  // instead of collapsing to one static string. {cause} stays raw English (a native
  // OS/addon error string with no translatable form); everything else is localized.
  'voice.reasonAddonMissing': 'the on-device speech engine could not be loaded ({cause})',
  'voice.reasonModelNotDownloaded': '{model} is not downloaded yet ({state}) — finish the download in Settings > Voice',
  'voice.reasonVadFailed': 'the voice-activity model could not be downloaded ({cause})',
  'voice.reasonUnknownModel': 'the selected model "{model}" is no longer available — pick another in Settings > Voice',
  'voice.reasonUnsupportedKind': 'model type "{kind}" has no on-device decoder',
  // (C1200) Both streaming (voice:*) and batch (POST /api/transcribe) failure paths used to be
  // silent — a recording could end with zero text and zero feedback. These two keys are the
  // last-resort signal shown when a recording ends having produced nothing at all: errStreamFailed
  // when the streaming leg reported a voice:error, noSpeech otherwise (streaming reported nothing
  // AND the batch fallback transcript was empty). See audio-recorder.js#reportNothingProduced.
  'voice.noSpeech': 'No speech detected — nothing was transcribed',
  'voice.errStreamFailed': 'Live transcription failed — {msg}',
  // (C1202) Three more zero-text causes reportNothingProduced()/voice-report.js can now tell
  // apart from plain "no speech": a blocked OS mic permission, a captured-but-silent track
  // (the packaged-macOS-app entitlement bug this task's root cause fixes), and a still-loading
  // local model whose recognizer hadn't finished building yet. errStreamUnsupported replaces
  // the old behavior of silently collapsing every voice:unsupported into voice.noSpeech.
  'voice.micBlocked': 'Microphone access is blocked for TipATask — enable it in System Settings > Privacy & Security > Microphone, then restart the app',
  'voice.micSilent': 'No sound reached the microphone — check the input device and permissions',
  'voice.modelLoading': 'The on-device model was still loading — try again in a moment',
  'voice.errStreamUnsupported': 'Transcription is not available right now — {reason}',
  // (C1202) Recording-toast hint shown while the local recognizer is still building — see
  // audio-recorder.js's onLoading wiring, same hint slot as voice.stoppingIn.
  'voice.loadingModel': 'Loading {model}…',
  // (C1204) Recording started against a specific input device (Settings > Voice) that no
  // longer resolves — device unplugged, or the saved id came from another machine's browser
  // profile. getUserMedia() retried with the system default so the recording still happens.
  'voice.deviceUnavailable': 'The selected microphone is unavailable — using the system default',
  // (TPT9158) Thank You mode (audio-recorder.js). sayStopPhrase is the recording toast's resting
  // hint; {phrase} is voice-stop-phrase.js's stopPhraseLabel() for the project language.
  // stopPhraseUnavailable replaces it while the live transcript is down and the phrase cannot
  // be heard. transcribing/cleaningUp name the two waits after the mic closes, on the busy mic
  // and in a progress toast.
  'voice.sayStopPhrase': 'Say “{phrase}” to finish',
  'voice.stopPhraseUnavailable': 'Can’t listen for “{phrase}” — press {shortcut} to finish',
  'voice.transcribing': 'Transcribing…',
  'voice.cleaningUp': 'Cleaning up the transcript…',

